        (wheel_torque_limit_nm == NULL) || (wheel_torque_nm == NULL) || 
        (achieved_body_torque_nm == NULL) || (saturation_mask == NULL)) {
        return ADCS_E_NULL;
    }

    // Check finiteness of vectors
    if (!adcs_is_finite_vec3(&wheel_axes_body[0]) || 
        !adcs_is_finite_vec3(&wheel_axes_body[1]) || 
        !adcs_is_finite_vec3(&wheel_axes_body[2]) || 
        !adcs_is_finite_vec3(desired_body_torque_nm)) {
        return ADCS_E_RANGE;
    }

    // Check finiteness of limits
    if (!isfinite(wheel_torque_limit_nm[0]) || 
        !isfinite(wheel_torque_limit_nm[1]) || 
        !isfinite(wheel_torque_limit_nm[2])) {
        return ADCS_E_RANGE;
    }

    // Validate the complete triad to 1e-10 norm/orthogonality tolerance
    const double tol = 1e-10;
    double d01 = adcs_vec3_dot(&wheel_axes_body[0], &wheel_axes_body[1]);
    double d02 = adcs_vec3_dot(&wheel_axes_body[0], &wheel_axes_body[2]);
    double d12 = adcs_vec3_dot(&wheel_axes_body[1], &wheel_axes_body[2]);

    if (fabs(d01) > tol || fabs(d02) > tol || fabs(d12) > tol) {
        return ADCS_E_RANGE;
    }

    double n0 = adcs_vec3_norm(&wheel_axes_body[0]);
    double n1 = adcs_vec3_norm(&wheel_axes_body[1]);
    double n2 = adcs_vec3_norm(&wheel_axes_body[2]);

    if (fabs(n0 - 1.0) > tol || fabs(n1 - 1.0) > tol || fabs(n2 - 1.0) > tol) {
        return ADCS_E_RANGE;
    }

