    wheel_torque_nm[0] = 0.0;
    wheel_torque_nm[1] = 0.0;
    wheel_torque_nm[2] = 0.0;
    achieved_body_torque_nm->x = 0.0;
    achieved_body_torque_nm->y = 0.0;
    achieved_body_torque_nm->z = 0.0;
    *saturation_mask = 0U;

    // Allocate, clamp, and reconstruct achieved torque
    adcs_vec3_t tau_ach = {0.0, 0.0, 0.0};

    for (int i = 0; i < 3; i++) {
        // Unconstrained motor command: u_i = - a_i . tau_desired
        double u_i = -adcs_vec3_dot(&wheel_axes_body[i], desired_body_torque_nm);

        double limit = wheel_torque_limit_nm[i];
        unint32 sat_bit = (unint32)(1U << i);

        // Clamp each u_i independently
        if (u_i > limit) {
            u_i = limit;
            *saturation_mask |= sat_bit;
        } else if (u_i < -limit) {
            u_i = -limit;
            *saturation_mask |= sat_bit;
        }

        wheel_torque_nm[i] = u_i;

        // Achieved spacecraft torque is -sum u_i a_i
        adcs_vec3_t term = adcs_vec3_scale(&wheel_axes_body[i], -u_i);
        tau_ach = adcs_vec3_add(&tau_ach, &term);
    }

    *achieved_body_torque_nm = tau_ach;

    return ADCS_OK;
}

